-- Event artwork plates for War Room alerts (KWC Alert Art Pack v1).
-- Presentation only. A plate is a plain texture drawn behind the existing toast
-- icon, live text, countdown and buttons. It never takes mouse input, never
-- changes what an alert says, and does not change when it fires or how it is
-- deduplicated. Assets: Media/Alerts/*.tga, generated by tools/alert_art.py from
-- docs/ALERT_ART.json.
local K=KWC
local Kit,S,T=K.Kit,K.WarRoomSkin,K.Toast
local OWNER=S.OWNER
local A={};K.AlertArt=A

local V=171/256          -- painted rows of the 512x256 power-of-two canvas
local ASPECT=512/171     -- painted plate aspect (3:1 master)
local BODY=0.62          -- share of plate height the toast body may occupy
local TEXT_LEFT=68       -- icon inset 16 + icon 40 + gap 12 (UI/Toast.lua)

-- key={file, cy=vertical centre of the dark text panel, label, level, tone, somber}
A.plates={
 honorableKill={file='Alerts\\HonorableKill',cy=0.47,label='Honorable kill',level='Standard',tone='good'},
 killingBlow={file='Alerts\\KillingBlow',cy=0.46,label='Killing blow',level='Heroic',tone='good'},
 killStreak={file='Alerts\\KillStreak',cy=0.49,label='Kill streak',level='Legendary',tone='accent'},
 fallen={file='Alerts\\Fallen',cy=0.50,label='Guildmate slain',level='Standard',tone='danger',somber=true},
 bountyPosted={file='Alerts\\BountyPosted',cy=0.50,label='Bounty posted',level='Standard',tone='warn'},
 bountySighting={file='Alerts\\BountySighting',cy=0.52,label='Bounty sighting',level='Standard',tone='warn'},
 bountyClaimed={file='Alerts\\BountyClaimed',cy=0.48,label='Bounty claimed / War Spoils',level='Heroic',tone='accent'},
 callToArms={file='Alerts\\CallToArms',cy=0.52,label='Call to Arms',level='Standard',tone='warn'},
 ctaVictory={file='Alerts\\CTAVictory',cy=0.50,label='CTA victory / guild milestone',level='Heroic',tone='accent'},
 commendation={file='Alerts\\Commendation',cy=0.49,label='Personal commendation',level='Standard',tone='accent'},
}
A.order={'honorableKill','killingBlow','killStreak','fallen','bountyPosted','bountySighting','bountyClaimed','callToArms','ctaVictory','commendation'}

-- Which plate an alert gets. content.art may name a plate explicitly, or be
-- false to keep the classic card. Channels without a mapping (Guild LFG) keep it.
function A.Resolve(channelKey,content)
 content=content or {}
 local art=content.art
 if art~=nil then return art and A.plates[art] and art or nil end
 if channelKey=='pvpKill' then
  return (content.evidence=='Reported own killing blow' or content.level=='Heroic') and 'killingBlow' or 'honorableKill'
 elseif channelKey=='worldPvPDeath' then return 'fallen'
 elseif channelKey=='bountyAlert' then return 'bountySighting'
 elseif channelKey=='ctaNotice' then return 'callToArms'
 elseif channelKey=='warCelebration' then
  local c=content.category
  if c=='streaks' then return 'killStreak'
  elseif c=='milestones' then return 'commendation'
  elseif c=='bounties' then return 'bountyClaimed'
  elseif c=='cta' or c=='guild' then return 'ctaVictory' end
  return content.level=='Legendary' and 'killStreak' or content.level=='Heroic' and 'ctaVictory' or 'commendation'
 end
 return nil
end

local function prefs() return K.Celebrations and K.Celebrations.Preferences() end
local function luminance(c) return c and (0.2126*c[1]+0.7152*c[2]+0.0722*c[3]) or 1 end
-- The painted plates are dark. Skins with dark text (light skins) keep their own
-- card so text contrast follows the theme engine instead of being forced.
function A.Enabled()
 local p=prefs()
 if p and p.eventArt==false then return false end
 return luminance(S.Color('text'))>=0.55
end
local function motion()
 local p=prefs()
 return not p or (p.animations~=false and not p.reducedMotion)
end

local function chrome(f,show)
 for _,region in ipairs(f.chrome or {}) do region:SetShown(show) end
end

local animate
local function parts(f)
 if f.plate then return end
 f.plate=f:CreateTexture(nil,'BACKGROUND',nil,3)
 f.plateGlint=f:CreateTexture(nil,'BACKGROUND',nil,4)
 if f.plateGlint.SetBlendMode then f.plateGlint:SetBlendMode('ADD') end
 -- Theme-tinted backing that follows the live text, so long names stay readable
 -- over the painted scene while short alerts leave the hero art untouched.
 f.scrim=f:CreateTexture(nil,'BORDER',nil,5)
 Kit.Paint(f.scrim,OWNER,'base','fill',0.6)
 f.scrimFade=f:CreateTexture(nil,'BORDER',nil,5)
 f.scrimFade:SetTexture(Kit.MEDIA..'Alerts\\ScrimFade')
 Kit.Paint(f.scrimFade,OWNER,'base','vertex',0.6)
 f.closeBack=f.close:CreateTexture(nil,'BACKGROUND')
 f.closeBack:SetPoint('TOPLEFT',2,-2);f.closeBack:SetPoint('BOTTOMRIGHT',-2,2)
 Kit.Paint(f.closeBack,OWNER,'base','fill',0.7)
 for _,t in ipairs({f.plate,f.plateGlint,f.scrim,f.scrimFade,f.closeBack}) do t:Hide() end
 f:HookScript('OnSizeChanged',function(self) if self.artKey then A.Layout(self) end end)
 f:HookScript('OnUpdate',animate)
 f:HookScript('OnHide',function(self) self.artAnimating=false end)
end

local function setPlate(f,scale)
 local w,h=f.artW*scale,f.artH*scale
 f.plate:SetSize(w,h);f.plateGlint:SetSize(w,h)
end

-- Sizes the plate from the toast body and centres the plate's text panel on it.
function A.Layout(f)
 local plate=f.artKey and A.plates[f.artKey];if not plate then return end
 local w,h=f:GetWidth(),f:GetHeight()
 if not w or not h or w<=0 or h<=0 then return end
 local pw=math.max(w*1.12,h/BODY*ASPECT)
 local ph=pw/ASPECT
 local dy=(plate.cy-0.5)*ph
 f.artW,f.artH,f.artDY=pw,ph,dy
 for _,t in ipairs({f.plate,f.plateGlint}) do
  t:ClearAllPoints();t:SetPoint('CENTER',f,'CENTER',0,dy);t:SetTexCoord(0,1,0,V)
 end
 setPlate(f,1)
 if f.SetClampRectInsets then
  local ox,oy=(pw-w)/2,(ph-h)/2
  f:SetClampRectInsets(-ox,ox,oy+dy,-(oy-dy))
 end
 A.Scrim(f)
end

-- Backing width follows the widest visible line (kicker, title, detail, meta).
function A.Scrim(f)
 if not f.artKey then return end
 local w,h=f:GetWidth(),f:GetHeight()
 local widest=0
 for _,fs in ipairs({f.kicker,f.title,f.detail,f.meta}) do
  local text=fs:GetText()
  if text and text~='' then widest=math.max(widest,fs:GetStringWidth() or 0) end
 end
 local solid=Kit.Clamp(TEXT_LEFT+widest+14,w*0.42,w-28)
 local fade=math.min(84,w-solid+20)
 f.scrim:ClearAllPoints();f.scrim:SetPoint('TOPLEFT',f,'TOPLEFT',0,-4);f.scrim:SetPoint('BOTTOMLEFT',f,'BOTTOMLEFT',0,4)
 f.scrim:SetWidth(solid)
 f.scrimFade:ClearAllPoints();f.scrimFade:SetPoint('TOPLEFT',f.scrim,'TOPRIGHT');f.scrimFade:SetPoint('BOTTOMLEFT',f.scrim,'BOTTOMRIGHT')
 f.scrimFade:SetWidth(fade)
 f.artScrim=solid
end

local function finish(f)
 f.artAnimating=false
 if f.artW then setPlate(f,1) end
 if f.plateGlint then f.plateGlint:SetAlpha(0);f.plateGlint:Hide() end
end

-- Arrival: a short settle (4.5% to 0) and a single additive glint for
-- celebratory plates. Off under Animations off or Reduced motion. The toast's
-- own fade and countdown are unchanged.
function animate(f,dt)
 if not f.artAnimating then return end
 if not motion() then finish(f);return end
 f.artClock=(f.artClock or 0)+(tonumber(dt) or 0)
 local t=f.artClock
 local k=math.min(1,t/0.28)
 setPlate(f,1+0.045*(1-k)^3)
 local g=(f.artGlintPeak or 0)*math.max(0,1-t/0.5)
 f.plateGlint:SetAlpha(g)
 if t>=0.5 then finish(f) end
end

local function clear(f)
 if not f.artKey then return end
 f.artKey,f.artAnimating=nil,false
 for _,t in ipairs({f.plate,f.plateGlint,f.scrim,f.scrimFade,f.closeBack}) do t:Hide() end
 if f.SetClampRectInsets then f:SetClampRectInsets(0,0,0,0) end
 chrome(f,true)
end

-- Called by Toast's Channel:Present after text and actions are set, before Show.
function A.Apply(ch,content)
 local f=ch.frame
 local key=A.Enabled() and A.Resolve(ch.key,content) or nil
 if not key then clear(f);return nil end
 parts(f)
 local plate=A.plates[key]
 local ok,loaded=pcall(f.plate.SetTexture,f.plate,Kit.MEDIA..plate.file)
 if not ok or loaded==false then clear(f);return nil end
 f.plateGlint:SetTexture(Kit.MEDIA..plate.file)
 f.artKey=key
 chrome(f,false)
 f.plate:Show();f.scrim:Show();f.scrimFade:Show();f.closeBack:Show()
 A.Layout(f)
 local level=content and content.level
 f.artGlintPeak=plate.somber and 0 or level=='Legendary' and 0.5 or level=='Heroic' and 0.32 or 0.16
 f.artClock=0
 if motion() then
  f.artAnimating=true
  setPlate(f,1.045)
  f.plateGlint:SetAlpha(f.artGlintPeak);f.plateGlint:SetShown(f.artGlintPeak>0)
 else finish(f) end
 return key
end
T.Decorate=A.Apply

-- Manual artwork preview (Alerts > Alert policy). Uses the existing celebration
-- channel as a preview: no Chronicle entry, no network traffic, works anywhere.
local cursor=0
function A.Preview(key)
 if not key then cursor=cursor%#A.order+1;key=A.order[cursor] end
 local plate=A.plates[key];if not plate then return false end
 local index=1
 for i,id in ipairs(A.order) do if id==key then index=i end end
 return K.Celebrations.Moment({art=key,level=plate.level,tone=plate.tone,
  kicker=('Artwork %d/%d  |  %s'):format(index,#A.order,plate.label),
  title=K.CharacterDisplayName(UnitName('player'),true),
  detail='Event artwork preview',meta='War Room'},true)
end
